package org.jlinalg.cli;

import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.regex.Pattern;
import org.jlinalg.sequence.FastqIO;
import org.jlinalg.sequence.ReadQualityTrimmer;
import static org.jlinalg.cli.FollowupSupport.*;

/** Explicit ordered quality/adapter trimming with complete paired/orphan fate and content audits. */
final class TrimmomaticToolsCli {
    private TrimmomaticToolsCli() { }
    private static final Set<String> OPTIONS=Set.of("engine","reads","reads2","phred","steps","home","java","threads","memory-mb","timeout","verbose","out");
    private static final Pattern LOG=Pattern.compile("^(.*) ([0-9]+) ([0-9]+) ([0-9]+) ([0-9]+)$");
    private static final List<String> OUTPUTS=List.of("read1.paired.fastq.gz","read1.unpaired.fastq.gz","read2.paired.fastq.gz","read2.unpaired.fastq.gz");
    private record Spec(String type,List<String> values) {Spec {values=List.copyOf(values);}String token(){return type+(values.isEmpty()?"":":"+String.join(":",values));}}
    private record Span(int length,int first,int end) {boolean retained(){return length>0;}}
    private static final class Counts {long units,inputBases,outputBases,both,only1,only2,dropped;void add(FastqIO.Read a,FastqIO.Read b,Span first,Span second){units++;inputBases+=a.sequence().length()+(b==null?0:b.sequence().length());outputBases+=first.length()+(second==null?0:second.length());if(first.retained()&&(second==null||second.retained()))both++;else if(first.retained())only1++;else if(second!=null&&second.retained())only2++;else dropped++;}}
    static int run(String[] args,PrintStream output,PrintStream error){
        if(Arrays.asList(args).contains("--help")){output.println(help());return 0;}
        try{
            var o=options(args,OPTIONS);String engine=required(o,"engine");if(!Set.of("native","upstream").contains(engine))throw new IllegalArgumentException("engine must be native or upstream");required(o,"reads");required(o,"steps");int phred=Integer.parseInt(required(o,"phred"));if(phred!=33&&phred!=64)throw new IllegalArgumentException("Explicit --phred33or64 required; no automatic encoding inference");if(engine.equals("upstream")){required(o,"home");integer(o,"threads",1,1,256);integer(o,"memory-mb",512,128,65536);integer(o,"timeout",3600,1,86400);bool(o,"verbose",false);}else for(String k:List.of("home","java","threads","memory-mb","timeout","verbose"))if(o.containsKey(k))throw new IllegalArgumentException("--"+k+" applies only to upstream mode");
            int[] code={0};externalTransaction(o,"trimmomatic-"+engine,(dir,manifest)->{
                var session=new LinkedHashMap<String,Object>();var warnings=new ArrayList<String>();var source=new LinkedHashMap<Path,String>();
                try{
                    TrimmomaticRuntime runtime=engine.equals("upstream")?new TrimmomaticRuntime(Path.of(o.get("home")),o.containsKey("java")?Path.of(o.get("java")):null,dir,session):null;Path steps=input(o.get("steps"),source);var specifications=specifications(steps,dir,source,runtime);Path read1=input(o.get("reads"),source),read2=o.containsKey("reads2")?input(o.get("reads2"),source):null;boolean paired=read2!=null;if(paired&&Files.isSameFile(read1,read2))throw new IOException("FASTQ mates must be distinct files");
                    inspect(read1,read2,phred);var staged=new LinkedHashMap<Path,String>();try(var files=Files.list(dir)){for(Path p:files.filter(p->p.getFileName().toString().equals("steps.tsv")||p.getFileName().toString().startsWith("adapters-step-")).toList())staged.put(p,hash(p));}int finalOffset=phred;for(var s:specifications)if(s.type().equals("TOPHRED33"))finalOffset=33;else if(s.type().equals("TOPHRED64"))finalOffset=64;
                    if(runtime==null){var pipeline=new ReadQualityTrimmer.Pipeline(specifications.stream().map(s->new ReadQualityTrimmer.Step(s.type(),s.values())).toList());nativeTrim(dir,read1,read2,phred,pipeline);session.put("implementation","Native ordered quality/length/MAXINFO steps; upstream-compatible tested subset, no adapter clipping");}
                    else{
                        if(runtime.version().equals("0.39")&&bool(o,"verbose",false))throw new IOException("Per-adapter verbose reporting requires Trimmomatic0.41; select that runtime or omit verbose");var command=new ArrayList<>(List.of(paired?"PE":"SE","-threads",Integer.toString(integer(o,"threads",1,1,256)),"-phred"+phred,"-trimlog",dir.resolve("trim.log").toString(),"-summary",dir.resolve("summary.txt").toString()));if(bool(o,"verbose",false))command.add("-verbose");command.add(read1.toString());if(paired)command.add(read2.toString());if(paired)for(String name:OUTPUTS)command.add(dir.resolve(name).toString());else command.add(dir.resolve("trimmed.fastq.gz").toString());for(var spec:specifications)command.add(spec.token());runtime.trim(dir,command,integer(o,"threads",1,1,256),integer(o,"memory-mb",512,128,65536),integer(o,"timeout",3600,1,86400));
                        for(String line:Files.readAllLines(dir.resolve("analysis.log")))if(line.toLowerCase(Locale.ROOT).contains("warning"))warnings.add("UPSTREAM: "+line.strip());session.put("implementation","Original Trimmomatic"+runtime.version()+"; explicit SE/PE, thread count and ordered steps");
                    }
                    Counts counts=audit(dir,read1,read2,phred,finalOffset);summaryAudit(dir,counts,paired);RegenieRuntime.verify(staged);var stagedHashes=new LinkedHashMap<String,String>();staged.forEach((p,h)->stagedHashes.put(p.getFileName().toString(),h));session.put("staged_input_sha256",stagedHashes);if(counts.units==0)throw new IOException("No input reads; no meaningful trimming analysis");if(counts.both+counts.only1+counts.only2==0)warnings.add("NO READS RETAINED: all input reads/pairs were removed. Inspect step order,quality thresholds,input lengths,adapter choice and explicit encoding before downstream analysis.");if(paired&&counts.both==0&&counts.only1+counts.only2>0)warnings.add("NO COMPLETE PAIRS: only orphan reads survived. Use the explicitly named unpaired files for single-end analysis or review the requested preprocessing; do not pass orphan files as paired mates.");if(counts.only1+counts.only2>0)warnings.add("ORPHANS RETAINED: "+counts.only1+" read1-only and "+counts.only2+" read2-only observations are in separate files. Complete pairs remain synchronized in the paired outputs.");if(finalOffset==64)warnings.add("PHRED64 OUTPUT: downstream tools must use the declared+64encoding. Select TOPHRED33 explicitly before Phred33-only workflows; no automatic conversion was applied.");if(specifications.stream().anyMatch(s->s.type().equals("TRAILING")))warnings.add("TRAILING BOUNDARY: upstream-compatible TRAILING rejects one-base reads even if high quality. Uppercase N contributes quality0; lowercase n is not normalized. These semantics are retained and tested.");
                    var result=new ArrayList<String[]>();for(var e:countMap(counts,paired).entrySet())result.add(new String[]{e.getKey(),Long.toString(e.getValue())});result.add(new String[]{"input_bases_both_mates",Long.toString(counts.inputBases)});result.add(new String[]{"output_bases_all_retained_files",Long.toString(counts.outputBases)});result.add(new String[]{"output_phred_offset",Integer.toString(finalOffset)});table(dir.resolve("results.tsv"),List.of("metric","value"),result);session.put("steps",specifications.stream().map(Spec::token).toList());session.put("input_phred",phred);session.put("output_phred",finalOffset);session.put("paired",paired);session.put("audit","Every original header,declared mate,trim span,base and corresponding converted quality verified in input order via trim.log; exact paired/orphan dispositions and summary counts. No sorting,read-ID collapsing or guessed defaults.");RegenieRuntime.verify(source);if(runtime!=null)runtime.verify();var hashes=new LinkedHashMap<String,String>();source.forEach((p,h)->hashes.put(p.toString(),h));manifest.put("source_sha256",hashes);manifest.put("analysis_status",warnings.isEmpty()?"completed":"completed-with-warnings");
                }catch(Exception e){code[0]=e instanceof TrimmomaticRuntime.Unavailable?3:2;manifest.put("analysis_status",code[0]==3?"skipped-dependency-unavailable":"failed");manifest.put("error",String.valueOf(e.getMessage()));RnaToolRuntime.quarantine(dir);warnings.add(0,(code[0]==3?"ANALYSIS SKIPPED: ":"ANALYSIS FAILED: ")+e.getMessage());}
                if(!warnings.isEmpty())Files.writeString(dir.resolve("WARNINGS.md"),"# "+(code[0]==3?"ANALYSIS SKIPPED - TRIMMOMATIC/JAVA UNAVAILABLE":code[0]==2?"TRIMMING ANALYSIS FAILED":"TRIMMING WARNINGS REQUIRE REVIEW")+"\n\n"+String.join("\n\n",warnings)+"\n\nRequired action: "+(code[0]==3?"Where permitted run python tools/literature/install_trimmomatic.py --allow-download --private-java --version 0.41, or supply the pinned program and a supported --java executable. If installation is forbidden/unavailable, skip the affected upstream analysis until a permitted runtime is supplied. Native quality/length trimming needs no extra runtime.":code[0]==2?"Inspect retained logs and the named pipeline,FASTQ,encoding,MAXINFO length,adapter or output-content contract. Correct the cause and rerun to a new directory. Failed partials remain under partial/; no successful results.tsv is published.":"Review step order,per-mate settings,actual retained counts,orphan files,encoding and assay-specific QC before downstream analysis. Original inputs remain unchanged; no downstream analysis was run.")+"\n");session.put("warnings",warnings);Files.writeString(dir.resolve("session.yaml"),new org.yaml.snakeyaml.Yaml().dump(session));Files.writeString(dir.resolve("analysis-status.json"),RegenieRuntime.json(Map.of("status",manifest.get("analysis_status")))+"\n");
            });if(code[0]!=0||Files.exists(Path.of(o.get("out"),"WARNINGS.md")))error.println((code[0]==3?"SKIPPED ANALYSIS":code[0]==2?"ANALYSIS FAILED":"ANALYSIS WARNINGS")+": see "+Path.of(o.get("out"),"WARNINGS.md"));if(code[0]==0)output.println("Trimming completed: "+o.get("out"));return code[0];
        }catch(Exception e){error.println("jlinalg: "+e.getMessage());return 2;}
    }
    private static int integer(Map<String,String> o,String k,int fallback,int low,int high){int n=Integer.parseInt(o.getOrDefault(k,Integer.toString(fallback)));if(n<low||n>high)throw new IllegalArgumentException("--"+k+" outside "+low+".."+high);return n;}
    private static boolean bool(Map<String,String> o,String k,boolean fallback){String v=o.getOrDefault(k,Boolean.toString(fallback));if(!Set.of("true","false").contains(v))throw new IllegalArgumentException("--"+k+" requires true/false");return Boolean.parseBoolean(v);}
    private static Path input(String text,Map<Path,String> source)throws IOException{Path p=RnaToolRuntime.file(text);String h=hash(p),old=source.putIfAbsent(p,h);if(old!=null&&!old.equals(h))throw new IOException("Source changed during preparation: "+p);return p;}
    private static List<Spec> specifications(Path file,Path dir,Map<Path,String> source,TrimmomaticRuntime runtime)throws IOException{
        var result=new ArrayList<Spec>();try(var in=Files.newBufferedReader(file)){if(!"step\targuments".equals(in.readLine()))throw new IOException("Pipeline requires first line step<TAB>arguments; subsequent fields vary by validated step");String line;int n=1;while((line=in.readLine())!=null){n++;if(line.isBlank()||line.startsWith("#"))continue;var f=line.split("\t",-1);String type=f[0];var values=new ArrayList<>(Arrays.asList(f).subList(1,f.length));try{
            if(type.equals("ILLUMINACLIP")){
                if(runtime==null)throw new IllegalArgumentException("ILLUMINACLIP requires original upstream mode; native quality steps do not substitute adapter clipping");if(values.size()<4||values.size()>6)throw new IllegalArgumentException("ILLUMINACLIP requires adapter-file/seed/palindrome/simple and optional min-prefix/keep-both");for(int i=1;i<=3;i++){int x=Integer.parseInt(values.get(i));if(x<0||x>(i==1?16:100000))throw new IllegalArgumentException("Invalid adapter threshold");}if(values.size()>4){int x=Integer.parseInt(values.get(4));if(x<1||x>10000)throw new IllegalArgumentException("Positive minimum palindrome length required");}if(values.size()>5){String value=values.get(5).toLowerCase(Locale.ROOT);if(!Set.of("true","false").contains(value))throw new IllegalArgumentException("keep-both must be true/false");values.set(5,value);}
                String adapter=values.get(0);Path original=adapter.startsWith("@")?runtime.adapter(adapter.substring(1)):Path.of(adapter);if(!original.isAbsolute())original=file.getParent().resolve(original);original=input(original.toString(),source);validateAdapters(original);String name="adapters-step-"+result.size()+".fa";Files.copy(original,dir.resolve(name));values.set(0,name);
            }else new ReadQualityTrimmer.Step(type,values);
            result.add(new Spec(type,values));if(result.size()>1000)throw new IllegalArgumentException("Pipeline exceeds1000explicit steps");
        }catch(IllegalArgumentException e){throw new IOException("Pipeline row"+n+": "+e.getMessage(),e);}}}if(result.isEmpty())throw new IOException("No explicit trimming steps");try(var out=Files.newBufferedWriter(dir.resolve("steps.tsv"))){out.write("step\targuments\n");for(var spec:result)out.write(spec.type()+(spec.values().isEmpty()?"":"\t"+String.join("\t",spec.values()))+"\n");}return List.copyOf(result);
    }
    private static void validateAdapters(Path file)throws IOException{
        var names=new HashSet<String>();String name=null;int bases=0;try(var in=Files.newBufferedReader(file)){String line;while((line=in.readLine())!=null){if(line.isBlank())continue;if(line.startsWith(">")){if(name!=null&&bases==0)throw new IOException("Empty adapter sequence");name=line.substring(1).split("\\s+",2)[0];if(name.isEmpty()||!names.add(name))throw new IOException("Duplicate/empty adapter name");bases=0;}else{if(name==null||line.chars().anyMatch(c->"ACGTNacgtn".indexOf(c)<0))throw new IOException("Adapter FASTA requires named DNA sequences using ACGTN");bases+=line.length();if(bases>100000)throw new IOException("Adapter sequence exceeds100000bases");}}}if(name==null||bases==0)throw new IOException("No nonempty adapter sequences");
    }
    private static void inspect(Path first,Path second,int offset)throws IOException{
        long n=0;try(var a=new FastqIO.Reader(first);var b=second==null?null:new FastqIO.Reader(second)){FastqIO.Read x;while((x=a.next())!=null){FastqIO.Read y=b==null?null:b.next();if(b!=null&&(y==null||!x.pairId().equals(y.pairId())))throw new IOException("FASTQ pair identity/order/count mismatch at record"+(n+1));checkInput(x,offset,b==null?0:1);if(y!=null)checkInput(y,offset,2);n++;}if(b!=null&&b.next()!=null)throw new IOException("FASTQ mate has extra records");}if(n==0)throw new IOException("Input FASTQ contains no reads");
    }
    private static void checkInput(FastqIO.Read read,int offset,int mate)throws IOException{
        if(read.sequence().isEmpty())throw new IOException("Nonempty input reads required; empty-read/zero-crop workflows need explicit separate handling");for(int i=0;i<read.quality().length();i++)if(read.quality().charAt(i)<offset)throw new IOException("Quality character below declared Phred offset; no encoding inference");String[] f=read.header().substring(1).split("\\s+",2);if(mate>0&&(f[0].endsWith("/1")&&mate!=1||f[0].endsWith("/2")&&mate!=2||f.length>1&&f[1].matches("[12]:[YN]:[0-9]+:.*")&&f[1].charAt(0)-'0'!=mate))throw new IOException("FASTQ header mate label disagrees with supplied file slot");
    }
    private static void nativeTrim(Path dir,Path first,Path second,int offset,ReadQualityTrimmer.Pipeline pipeline)throws IOException{
        try(var a=new FastqIO.Reader(first);var b=second==null?null:new FastqIO.Reader(second);var p1=new FastqIO.Writer(dir.resolve(second==null?"trimmed.fastq.gz":OUTPUTS.get(0)));var p2=second==null?null:new FastqIO.Writer(dir.resolve(OUTPUTS.get(2)));var u1=second==null?null:new FastqIO.Writer(dir.resolve(OUTPUTS.get(1)));var u2=second==null?null:new FastqIO.Writer(dir.resolve(OUTPUTS.get(3)));var log=Files.newBufferedWriter(dir.resolve("trim.log"))){FastqIO.Read x;while((x=a.next())!=null){FastqIO.Read y=b==null?null:b.next();if(b!=null&&(y==null||!x.pairId().equals(y.pairId())))throw new IOException("FASTQ pair changed after preflight");var r1=pipeline.apply(x,offset,false);var r2=y==null?null:pipeline.apply(y,offset,true);if(r1.retained())writeRetained(r2==null||r2.retained()?p1:u1,r1.read());if(r2!=null&&r2.retained())writeRetained(r1.retained()?p2:u2,r2.read());writeLog(log,x,r1);if(y!=null)writeLog(log,y,r2);}if(b!=null&&b.next()!=null)throw new IOException("FASTQ mate changed after preflight");}
    }
    private static void writeRetained(FastqIO.Writer out,FastqIO.Read read)throws IOException{if(read.quality().chars().anyMatch(c->c>126))throw new IOException("Output Phred64 cannot represent a source score above62in ASCII FASTQ; select TOPHRED33");out.write(read);}
    private static void writeLog(BufferedWriter out,FastqIO.Read original,ReadQualityTrimmer.Result result)throws IOException{out.write(original.header().substring(1)+" "+(result.retained()?result.read().sequence().length()+" "+result.first()+" "+result.end()+" "+(original.sequence().length()-result.end()):"0 0 0 0")+"\n");}
    private static Span span(BufferedReader log,FastqIO.Read original)throws IOException{
        String line=log.readLine();if(line==null)throw new IOException("Trim log omitted original reads");var m=LOG.matcher(line);if(!m.matches()||!m.group(1).equals(original.header().substring(1)))throw new IOException("Trim log changed original header/order");int length=Integer.parseInt(m.group(2)),first=Integer.parseInt(m.group(3)),end=Integer.parseInt(m.group(4)),last=Integer.parseInt(m.group(5));if(length==0){if(first!=0||end!=0||last!=0)throw new IOException("Invalid dropped-read log geometry");}else if(end-first!=length||end>original.sequence().length()||last!=original.sequence().length()-end)throw new IOException("Trim log bounds/bases differ from original read");return new Span(length,first,end);
    }
    private static void verify(FastqIO.Reader output,FastqIO.Read original,Span span,int inputOffset,int outputOffset)throws IOException{
        StringBuilder expected=new StringBuilder();for(int i=span.first();i<span.end();i++){int q=original.quality().charAt(i)-inputOffset+outputOffset;if(q>126)throw new IOException("Output Phred64 cannot represent a source score above62in ASCII FASTQ; select TOPHRED33");expected.append((char)q);}FastqIO.Read actual=output.next();if(actual==null||!actual.header().equals(original.header())||!actual.sequence().equals(original.sequence().substring(span.first(),span.end())))throw new IOException("Retained FASTQ header/sequence differs from original trim span");if(!actual.quality().contentEquals(expected))throw new IOException("Retained FASTQ qualities differ from original span/explicit encoding conversion");
    }
    private static Counts audit(Path dir,Path first,Path second,int inputOffset,int outputOffset)throws IOException{
        var counts=new Counts();try(var a=new FastqIO.Reader(first);var b=second==null?null:new FastqIO.Reader(second);var p1=new FastqIO.Reader(dir.resolve(second==null?"trimmed.fastq.gz":OUTPUTS.get(0)));var p2=second==null?null:new FastqIO.Reader(dir.resolve(OUTPUTS.get(2)));var u1=second==null?null:new FastqIO.Reader(dir.resolve(OUTPUTS.get(1)));var u2=second==null?null:new FastqIO.Reader(dir.resolve(OUTPUTS.get(3)));var log=Files.newBufferedReader(dir.resolve("trim.log"));var status=Files.newBufferedWriter(dir.resolve("read-status.tsv"))){status.write("input_ordinal\tread1_header_json\tread2_header_json\tdisposition\tread1_first\tread1_end\tread2_first\tread2_end\n");FastqIO.Read x;while((x=a.next())!=null){FastqIO.Read y=b==null?null:b.next();if(b!=null&&(y==null||!x.pairId().equals(y.pairId())))throw new IOException("FASTQ pair changed during output audit");Span s1=span(log,x),s2=y==null?null:span(log,y);if(s1.retained())verify(s2==null||s2.retained()?p1:u1,x,s1,inputOffset,outputOffset);if(s2!=null&&s2.retained())verify(s1.retained()?p2:u2,y,s2,inputOffset,outputOffset);counts.add(x,y,s1,s2);String disposition=s1.retained()&&(s2==null||s2.retained())?(s2==null?"single-retained":"both-retained"):s1.retained()?"read1-only":s2!=null&&s2.retained()?"read2-only":"dropped";status.write(counts.units+"\t"+RegenieRuntime.json(x.header())+"\t"+(y==null?"NA":RegenieRuntime.json(y.header()))+"\t"+disposition+"\t"+s1.first()+"\t"+s1.end()+"\t"+(s2==null?"NA":s2.first())+"\t"+(s2==null?"NA":s2.end())+"\n");}if(log.readLine()!=null||p1.next()!=null||b!=null&&(b.next()!=null||p2.next()!=null||u1.next()!=null||u2.next()!=null))throw new IOException("Extra source/log/retained observations after full audit");}return counts;
    }
    private static Map<String,Long> countMap(Counts c,boolean paired){var m=new LinkedHashMap<String,Long>();m.put(paired?"Input Read Pairs":"Input Reads",c.units);m.put(paired?"Both Surviving Reads":"Surviving Reads",c.both);if(paired){m.put("Forward Only Surviving Reads",c.only1);m.put("Reverse Only Surviving Reads",c.only2);}m.put("Dropped Reads",c.dropped);return m;}
    private static void summaryAudit(Path dir,Counts counts,boolean paired)throws IOException{
        Map<String,Long> expected=countMap(counts,paired);Path file=dir.resolve("summary.txt");if(!Files.exists(file)){try(var out=Files.newBufferedWriter(file)){for(var e:expected.entrySet())out.write(e.getKey()+": "+e.getValue()+"\n");}return;}var observed=new HashMap<String,Long>();for(String line:Files.readAllLines(file)){String[] f=line.split(":",2);if(f.length==2&&expected.containsKey(f[0])){if(observed.put(f[0],Long.valueOf(f[1].strip()))!=null)throw new IOException("Duplicate upstream summary count");}}if(!expected.equals(observed))throw new IOException("Original upstream summary counts differ from every audited read disposition");
    }
    static String help(){return """
        trimmomatic-tools --engine native|upstream --reads R1.fq[.gz] [--reads2 R2.fq[.gz]]
          --phred 33|64 --steps PIPELINE.tsv --out NEW_DIR
        Pipeline first line: step<TAB>arguments. Each subsequent row is a step name followed by
          TAB-separated parameters; optional blank/#comment lines. Order is literal and explicit.
          Native: LEADING/TRAILING/AVGQUAL quality; SLIDINGWINDOW window quality; CROP/MINLEN/MAXLEN
          length; HEADCROP/TAILCROP bases [maxLength [secondBases secondMaxLength]];
          BASECOUNT literalBases [min [max]]; TOPHRED33/TOPHRED64; MAXINFO targetLength strictness.
          CROP/maxLength must be positive; nonempty input reads required. MAXINFO has the upstream
          1000-base limit at that step; no automatic cropping/parameter changes. Uppercase N has
          quality0, lowercase n unchanged. TRAILING rejects one-base reads like upstream.
        Upstream additionally supports ILLUMINACLIP adapter-file seedMismatch palindrome simple
          [minimumPalindrome [keepBoth]], with fields separated by TAB, not path colons.
          Adapter paths are relative to the pipeline; @NAME.fa selects a verified private bundled
          adapter. Copies receive safe relative names before original program execution.
          --home build/omics-trimmomatic/0.41 [--java EXE] --threads 1 --memory-mb 512
          --timeout 3600 --verbose false. Original0.39 or0.41;0.41 requires Java25+.
          No simplified/default pipeline, inferred quality encoding or silently substituted adapter.
        All original headers,trim geometry,bases/qualities,pair order and summary counts audited.
          PE retains four paired/orphan files; SE has trimmed.fastq.gz. read-status.tsv,trim.log,
          source hashes,actual JVM/version,command and warnings retained. Native needs no external
          program. Program/JVM unavailable skip3; failed analysis2 retains partials/no success table.
          All-filtered/orphan/Phred64 findings remain prominent before downstream analysis.
        """;}
}
